// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

/**
 * Lifecycle regression tests for the asynchronous LMDB writer.
 */
public final class LmdbSailStoreShutdownTest {

	private static final String PROBE_MODE = "async-writer-shutdown";

	@TempDir(cleanup = CleanupMode.ON_SUCCESS)
	Path tempDir;

	@Test
	void shutdownCompletesAfterAnAsyncWriterReachesItsIdleTransaction() throws Exception {
		Path outputFile = tempDir.resolve("async-writer-shutdown.log");
		Path storeDir = tempDir.resolve("store");
		String javaBinary = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process process = new ProcessBuilder(javaBinary, "--enable-native-access=ALL-UNNAMED", "-cp",
				System.getProperty("java.class.path"), LmdbSailStoreShutdownTest.class.getName(), PROBE_MODE,
				storeDir.toString())
						.redirectErrorStream(true)
						.redirectOutput(outputFile.toFile())
						.start();
		try {
			boolean finished = process.waitFor(15, TimeUnit.SECONDS);
			if (!finished) {
				String threadDump = captureThreadDump(process, outputFile);
				process.destroyForcibly();
				boolean exited = process.waitFor(5, TimeUnit.SECONDS);
				String output = readOutput(outputFile);
				assertTrue(exited && !process.isAlive(),
						"shutdown probe could not be forcibly terminated (output=" + outputFile + ", thread dump="
								+ threadDump + "):\n" + output);
				fail("shutdown probe timed out (output=" + outputFile + ", thread dump=" + threadDump + "):\n"
						+ output);
			}

			String output = readOutput(outputFile);
			assertEquals(0, process.exitValue(), "shutdown probe output (" + outputFile + "):\n" + output);
			assertTrue(output.contains("PROBE_ASYNC_WRITER_IDLE"), output);
			assertTrue(output.contains("PROBE_SHUTDOWN_COMPLETE"), output);
			assertTrue(output.contains("PROBE_CONNECTION_CLOSE_COMPLETE"), output);
			assertTrue(output.contains("PROBE_PENDING_ABORTED"), output);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				assertTrue(process.waitFor(5, TimeUnit.SECONDS),
						"shutdown probe remained alive during cleanup (output=" + outputFile + ")");
			}
		}
	}

	private static String captureThreadDump(Process process, Path outputFile) {
		Path threadDumpFile = outputFile.resolveSibling(outputFile.getFileName() + ".threads");
		File jcmd = Path.of(System.getProperty("java.home"), "bin", "jcmd").toFile();
		Process dump = null;
		try {
			dump = new ProcessBuilder(jcmd.getAbsolutePath(), Long.toString(process.pid()), "Thread.print")
					.redirectErrorStream(true)
					.redirectOutput(threadDumpFile.toFile())
					.start();
			boolean finished = dump.waitFor(5, TimeUnit.SECONDS);
			if (!finished) {
				dump.destroyForcibly();
				if (!dump.waitFor(5, TimeUnit.SECONDS)) {
					return "unavailable (jcmd did not exit; file=" + threadDumpFile + ")";
				}
			}
			return threadDumpFile + ":\n" + readOutput(threadDumpFile);
		} catch (IOException e) {
			return "unavailable (" + e + ")";
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			return "unavailable (interrupted while running jcmd)";
		} finally {
			if (dump != null && dump.isAlive()) {
				dump.destroyForcibly();
			}
		}
	}

	private static String readOutput(Path outputFile) throws IOException {
		return Files.exists(outputFile) ? Files.readString(outputFile, StandardCharsets.UTF_8) : "";
	}

	public static void main(String[] args) throws Exception {
		if (args.length != 2 || !PROBE_MODE.equals(args[0])) {
			throw new IllegalArgumentException("expected async-writer-shutdown mode and data directory");
		}
		runShutdownProbe(new File(args[1]));
	}

	private static void runShutdownProbe(File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		store.init();
		store.setConnectionTimeOut(200);
		IRI pendingSubject = SimpleValueFactory.getInstance().createIRI("urn:shutdown-pending-subject");
		IRI pendingPredicate = SimpleValueFactory.getInstance().createIRI("urn:shutdown-pending-predicate");
		IRI pendingObject = SimpleValueFactory.getInstance().createIRI("urn:shutdown-pending-object");
		try (NotifyingSailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			IRI subject = SimpleValueFactory.getInstance().createIRI("urn:shutdown-subject");
			IRI predicate = SimpleValueFactory.getInstance().createIRI("urn:shutdown-predicate");
			IRI object = SimpleValueFactory.getInstance().createIRI("urn:shutdown-object");
			connection.addStatement(subject, predicate, object);
			// addStatement queues the asynchronous writer operation. removeStatements waits for its StatefulOperation
			// to
			// finish, and this public read verifies that the queued add was consumed before the idle marker is emitted.
			connection.removeStatements(subject, predicate, object);
			assertFalse(connection.hasStatement(subject, predicate, object, true));
			// Leave a distinct write uncommitted so shutdown must abort the writer transaction rather than merely stop
			// it.
			connection.addStatement(pendingSubject, pendingPredicate, pendingObject);
			System.out.println("PROBE_ASYNC_WRITER_IDLE");
			store.shutDown();
			System.out.println("PROBE_SHUTDOWN_COMPLETE");
		}
		System.out.println("PROBE_CONNECTION_CLOSE_COMPLETE");

		LmdbStore reopened = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		try {
			reopened.init();
			reopened.setConnectionTimeOut(200);
			try (NotifyingSailConnection connection = reopened.getConnection()) {
				assertFalse(connection.hasStatement(pendingSubject, pendingPredicate, pendingObject, true));
			}
		} finally {
			reopened.shutDown();
		}
		System.out.println("PROBE_PENDING_ABORTED");
	}
}
